import { expect } from "@playwright/test";
import { APP_URL, API_URL } from "./urls";

/***
 * MARK: shared canary helpers
 * @description Single home for the fixtures every canary spec needs: app
 *   readiness, project selection, scratch-backend seeding (reset, task
 *   creation), inspector open/close, font settling for geometry assertions,
 *   and small geometry/text utilities. Extracted (task bf5695e4) from the
 *   per-file copies that used to drift apart — new specs must import from
 *   here instead of redefining these.
 * @example import { waitForAppReadyOnProject, createTaskViaApi } from "./helpers";
 ***/

export const API_BASE = API_URL;

/***
 * MARK: APP_READY_TIMEOUT_MS
 * @description Budget for the app-readiness gate: first paint plus the
 *   API-backed project fetch on a loaded gate host (cold vite compile,
 *   a sibling gate suite on shared CPUs, swap pressure). The 15s value
 *   this replaces dated from an idle dev box and reds the whole canary
 *   phase overnight on the 4-core homelab runners. Must stay within the
 *   suite's per-test timeout (see `timeout` in playwright.config.js) so a
 *   genuinely hung app still fails its test instead of stalling the gate.
 * @example await expect(btn).toBeVisible({ timeout: APP_READY_TIMEOUT_MS })
 ***/
export const APP_READY_TIMEOUT_MS = 60000;

export const MOBILE_VIEWPORT = { width: 375, height: 667 };
export const SHORT_MOBILE_VIEWPORT = { width: 375, height: 568 };
export const DESKTOP_VIEWPORT = { width: 1280, height: 720 };

/***
 * MARK: waitForAppReady
 * @description Loads the app and waits until the project selector (backed by
 *   the API) is visible, which means projects have loaded and an active
 *   project has been selected. Does NOT pin the active project — use
 *   `waitForAppReadyOnProject` when the spec's API assertions target one
 *   specific project. One bounded reload+retry inside the standard budget
 *   heals blank-root module-burst resource windows (failed loads must be
 *   re-issued, never waited out).
 * @example await waitForAppReady(page)
 * @param {import("@playwright/test").Page} page
 * @param {Object} [opts] - Options.
 * @param {number} [opts.readyTimeoutMs=APP_READY_TIMEOUT_MS] - Total
 *   readiness budget, split across the first attempt and the one bounded
 *   reload+retry (multi-navigation specs pass a smaller budget per load so
 *   the summed worst case stays inside the per-test timeout).
 ***/
export async function waitForAppReady(page, { readyTimeoutMs = APP_READY_TIMEOUT_MS } = {}) {
	try {
		await page.goto(APP_URL, { waitUntil: "domcontentloaded" });
	} catch (err) {
		// One bounded re-issue for transient gate-host resource windows
		// (net::ERR_INSUFFICIENT_RESOURCES across the module burst, or a
		// renderer that died under parallel-suite load): the failed load
		// must be re-issued — waiting longer cannot heal it. Any other
		// navigation error (dead backend, bad URL) throws immediately, and
		// a genuinely broken shell fails the retry and stays red. The
		// one-second backoff lets the resource window pass — an immediate
		// re-issue was observed landing inside the same window.
		if (!/ERR_INSUFFICIENT_RESOURCES|has been closed|Target closed|Page crashed|Target crashed/.test(err?.message || "")) throw err;
		await new Promise((r) => setTimeout(r, 1000));
		await page.goto(APP_URL, { waitUntil: "domcontentloaded" });
	}
	await expect(page).toHaveTitle(/Kainbain/);
	const totalBudget = Number.isFinite(readyTimeoutMs) && readyTimeoutMs > 0 ? readyTimeoutMs : APP_READY_TIMEOUT_MS;
	const firstHalf = Math.max(1000, Math.floor(totalBudget / 2));
	const secondHalf = Math.max(1000, totalBudget - firstHalf);
	try {
		await expect(page.getByRole("button", { name: /Project/i }).first()).toBeVisible({
			timeout: firstHalf,
		});
	} catch (err) {
		// Blank-root resource window (net::ERR_INSUFFICIENT_RESOURCES across
		// the vite module burst AFTER navigation commits: title loads, but a
		// hundred module requests fail and React never mounts): a longer wait
		// cannot heal it — the failed loads must be re-issued. One bounded
		// reload+retry with the budget's second half (same total as the old
		// single wait); a genuinely broken shell fails twice and stays red.
		// Mirrors the accessibility spec's waitForAppShell retry.
		await page.reload({ waitUntil: "domcontentloaded" });
		await expect(page).toHaveTitle(/Kainbain/);
		await expect(page.getByRole("button", { name: /Project/i }).first()).toBeVisible({
			timeout: secondHalf,
		});
	}
}

/***
 * MARK: selectProject
 * @description Pins the UI's active project to `name` via the project
 *   selector menu. No-op when that project is already active. Anchored to
 *   the selector's "Project:" prefix so the lookup never collides with the
 *   workflow switcher once named workflows load.
 * @example await selectProject(page, "Project A")
 * @param {import("@playwright/test").Page} page
 * @param {string} name - Project name, e.g. "Project A".
 ***/
export async function selectProject(page, name) {
	const active = page.getByRole("button", { name: new RegExp(name, "i") });
	if (await active.isVisible().catch(() => false)) {
		return;
	}
	await page.getByRole("button", { name: /^Project:/ }).click();
	// The selector is a dialog+listbox (role="option" rows) since the
	// ProjectMenu rewrite; fall back to role="menuitem" for older builds.
	const item = page.getByRole("option", { name }).or(page.getByRole("menuitem", { name }));
	if (await item.isVisible().catch(() => false)) {
		await item.click();
		await expect(page.getByRole("button", { name: new RegExp(name, "i") })).toBeVisible();
	}
}

/***
 * MARK: waitForAppReadyOnProject
 * @description `waitForAppReady` plus pinning the UI's active project to
 *   `name` (default "Project A") — the same project the spec's API
 *   assertions target. A fresh browser context otherwise defaults to the

